import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");

  useEffect(() => {
    fetchAllUsers();
  }, []);

  const fetchAllUsers = async () => {
    const studentRes = await axios.get("http://localhost:5000/api/student");
    const supervisorRes = await axios.get("http://localhost:5000/api/facultyadvisor");
    const evaluatorRes = await axios.get("http://localhost:5000/api/evaluator");

    setStudents(studentRes.data);
    setSupervisors(supervisorRes.data);
    setEvaluators(evaluatorRes.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      let res = await axios.post("http://localhost:5000/api/user", {
        username: name,
        email,
        password,
        role
      });

      const userId = res.data._id;

      if (role === "Student") {
        const student = {
          userId,
          studentName: name,
          regNo: registrationNumber,
          isGrouped: false
        };
        await axios.post("http://localhost:5000/api/student", student);
      } else if (role === "Supervisor") {
        const supervisor = {
          userId,
          Name: name,
          Meetings: []
        };
        await axios.post("http://localhost:5000/api/facultyadvisor", supervisor);
      } else if (role === "Evaluator") {
        await axios.post("http://localhost:5000/api/evaluator", {
          userId,
          name
        });
      }

      await fetchAllUsers();
      setName("");
      setEmail("");
      setPassword("");
      setRole("");
      setRegistrationNumber("");
    } catch (error) {
      console.error("Error submitting user:", error);
      alert("An error occurred. Please check console.");
    }
  };

  const handleEdit = (index, type) => {
    setEditingIndex(index);
    setEditingType(type);
    const user =
      type === "student"
        ? students[index]
        : type === "supervisor"
        ? supervisors[index]
        : evaluators[index];

    setName(user.studentName || user.Name || user.name);
    setEmail(""); // Emails are in the User model, requires separate query if needed
    setRole(type === "student" ? "Student" : type === "supervisor" ? "Supervisor" : "Evaluator");
    setPassword(""); // Not fetched from backend
    setRegistrationNumber(user.regNo || "");
  };

  const handleDelete = async (userId, type) => {
    try {
      await axios.delete(`http://localhost:5000/api/user/${userId}`);
      if (type === "student") {
        await axios.delete(`http://localhost:5000/api/student/${userId}`);
      } else if (type === "supervisor") {
        await axios.delete(`http://localhost:5000/api/facultyadvisor/${userId}`);
      } else if (type === "evaluator") {
        await axios.delete(`http://localhost:5000/api/evaluator/${userId}`);
      }

      await fetchAllUsers();
      alert("User deleted successfully.");
    } catch (error) {
      console.error("Error deleting user:", error);
    }
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (newPassword) {
      try {
        await axios.put(`http://localhost:5000/api/user/reset-password/${userId}`, {
          password: newPassword
        });
        alert("Password reset successfully.");
      } catch (error) {
        console.error("Password reset failed:", error);
      }
    }
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <p>Add or edit accounts for students, supervisors, and evaluators</p>

          <div className="user-form-container">
            <form onSubmit={handleSubmit} className="user-form">
              <label>Name</label>
              <input type="text" value={name} onChange={(e) => setName(e.target.value)} required />

              <label>Email</label>
              <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />

              <label>Password</label>
              <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />

              <label>Role</label>
              <select value={role} onChange={(e) => setRole(e.target.value)} required>
                <option value="">Select Role</option>
                <option value="Student">Student</option>
                <option value="Supervisor">Supervisor</option>
                <option value="Evaluator">Evaluator</option>
              </select>

              {role === "Student" && (
                <>
                  <label>Registration Number</label>
                  <input type="text" value={registrationNumber} onChange={(e) => setRegistrationNumber(e.target.value)} required />
                </>
              )}

              <button type="submit">{editingIndex !== null ? "Update" : "Submit"}</button>
            </form>
          </div>

          {/* Render Tables */}
          {students.length > 0 && (
            <div className="student-table">
              <h2>Students</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Reg No</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((s, i) => (
                    <tr key={i}>
                      <td>{s.studentName}</td>
                      <td>{s.regNo}</td>
                      <td>
                        <button onClick={() => handleEdit(i, "student")}>Edit</button>
                        <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(s.userId, "student")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {supervisors.length > 0 && (
            <div className="supervisor-table">
              <h2>Supervisors</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {supervisors.map((s, i) => (
                    <tr key={i}>
                      <td>{s.Name}</td>
                      <td>
                        <button onClick={() => handleEdit(i, "supervisor")}>Edit</button>
                        <button onClick={() => handleResetPassword(s.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(s.userId, "supervisor")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {evaluators.length > 0 && (
            <div className="evaluator-table">
              <h2>Evaluators</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {evaluators.map((e, i) => (
                    <tr key={i}>
                      <td>{e.name}</td>
                      <td>
                        <button onClick={() => handleEdit(i, "evaluator")}>Edit</button>
                        <button onClick={() => handleResetPassword(e.userId)}>Reset Password</button>
                        <button onClick={() => handleDelete(e.userId, "evaluator")}>Delete</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
